    'RegisterSimpleRisk'=>'Бүртгүүлэх SimpleRisk',
    'RegistrationText'=>'Бүртгэгдсэн SimpleRisk тохиолдлуудад Шинэчлэх болон Аюулгүй Хяналтын Хүрээ (SCF) Нэмэлтүүдэд нэн даруй хандах эрх олгоно. Upgrade Extra нь нэг товчлуур дээр дарснаар SimpleRisk жишээгээ нөөцлөх, шинэчлэх боломжийг олгодог. Secure Controls Framework (SCF) Extra нь SimpleRisk Governance функцид нэгдсэн хяналтын нийтлэг тогтолцоог бий болгодог. SimpleRisk-г бүртгүүлсний дараа таны бүртгэлийн мэдээллийг SimpleRisk-ийн байршуулсан сервер рүү илгээх болно. Өгөгдсөн бүртгэлийн мэдээллийг SimpleRisk хэрэглэгчдэд шинэ хувилбарууд болон аюулгүй байдлын шинэчлэлтүүдийг мэдэгдэхэд ашиглах болно. SimpleRisk-ийг бүртгүүлснээр та манай маркетингийн харилцаанд хамрагдах боломжтой, гэхдээ та эдгээр харилцаан дахь бүртгэлийг цуцлах холбоосыг ашиглан хүссэн үедээ татгалзаж болно. SimpleRisk нь үйлчлүүлэгчдийнхээ хувийн нууцыг хүндэтгэдэг бөгөөд SimpleRisk бүртгэлийн үйл явцаар дамжуулан бидэнд өгсөн мэдээллийг хэзээ ч гуравдагч этгээдэд зарахгүй.',
