    'QuestionnaireCompletedAuditLogViaApi' => '"{$user_name} " хэрэглэгч API-ээр дамжуулан "{$questionnaire_name}" холбоо барих "{$contact_name}" асуулгын хуудсыг бөглөсөн.',
