    'SetApplicabilityForControl' => 'Хэрэглэх тохиргоо: {$name}',
    'ApplicabilityAppliesToControl' => 'Үүнийг зөвхөн "{$name}"-ийн эсрэг бичих болно.',

    // Task 17: the Statement of Applicability report itself
