    'SoaImplementedPartial' => 'Хэсэгчилсэн',

    // The cover block.
    'SoaGeneratedOn' => 'Үүсгэсэн огноо',
    'SoaExcludedCount' => 'Хасагдсан',

    // The prompt shown when the framework has never been given the two cover
